 private KeyPair identity()throws Exception{if(identity!=null)return identity;KeyFactory factory=KeyFactory.getInstance("RSA");File privateFile=new File(getFilesDir(),"kontur-adb-private"),publicFile=new File(getFilesDir(),"kontur-adb-public");if(privateFile.isFile()&&publicFile.isFile()){identity=new KeyPair(factory.generatePublic(new X509EncodedKeySpec(read(publicFile,8192))),factory.generatePrivate(new PKCS8EncodedKeySpec(read(privateFile,8192))));}else{KeyPairGenerator generator=KeyPairGenerator.getInstance("RSA");generator.initialize(2048);identity=generator.generateKeyPair();try(FileOutputStream out=openFileOutput(privateFile.getName(),MODE_PRIVATE)){out.write(identity.getPrivate().getEncoded());}try(FileOutputStream out=openFileOutput(publicFile.getName(),MODE_PRIVATE)){out.write(identity.getPublic().getEncoded());}}return identity;}
