 private void verify()throws Exception{String[] fields=shell("getprop ro.product.device; getprop ro.build.version.incremental; getprop ro.build.version.sdk; id -u; cat /sys/fs/selinux/enforce; cat /proc/sys/kernel/random/boot_id").split("\n");if(fields.length!=6||!fields[0].equals("yandexstation_2")||!fields[1].equals("5000000921")||!fields[2].equals("28"))throw new IOException("Для этой модели или сборки нет проверенного профиля. Изменений нет.");queue=!fields[3].equals("0");if(queue){String status=shell("cat /data/local/tmp/rootstatus 2>/dev/null || true");if(!status.contains("state=PROTECTED")||!status.contains("profile=0921"))throw new IOException("ADB доступен, но root не подтверждён. Сначала завершите получение root в AliceBridge.");}if(!fields[4].equals("0"))throw new IOException("Root-профиль ещё не переведён в Permissive. Проверьте состояние AliceBridge.");boot=fields[5];agent=shell("test -f /odm/bin/station-panel-v2 && test -f /odm/etc/init/station-panel.rc && echo installed || echo absent").equals("installed");}
