 private static byte[] read(File file,int max)throws Exception{try(InputStream in=new FileInputStream(file);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>max)throw new IOException("Слишком большой файл комплекта");}return out.toByteArray();}}
 private static String sha(byte[] b)throws Exception{return PublicUpdates.hex(MessageDigest.getInstance("SHA-256").digest(b));}
 private Map<String,byte[]> unpack(byte[] zip)throws Exception{Map<String,byte[]> entries=new HashMap<>();int total=0,count=0;try(ZipInputStream in=new ZipInputStream(new ByteArrayInputStream(zip))){ZipEntry entry;while((entry=in.getNextEntry())!=null){String name=entry.getName();if(++count>512||name.contains("..")||name.startsWith("/")||name.contains("\\")||entries.containsKey(name))throw new IOException("Некорректный комплект установки");if(entry.isDirectory())continue;ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);total+=n;if(out.size()>32*1024*1024||total>96*1024*1024)throw new IOException("Комплект слишком большой");}if(name.equals("manifest.json")||name.equals("install-device.sh")||name.equals("rollback-device.sh")||name.startsWith("payload/"))entries.put(name,out.toByteArray());}}return entries;}
 private void root(String script,String stage,boolean wait)throws Exception{if(!queue){try(NativeAdb adb=new NativeAdb(target,targetPort,identity(),LanNetwork.find(BootstrapActivity.this,target))){adb.timeout(180000);adb.shell(script);}return;}String id="studio-"+UUID.randomUUID().toString().replace("-","").substring(0,16),name=stage+"/request.sh";push(name,(script+"\n").getBytes("UTF-8"));shell("chown 2000:2000 "+name+" && chmod 0660 "+name+" && mv "+name+" /data/local/tmp/rootcmd-"+id);if(!wait)return;long deadline=System.currentTimeMillis()+180000;while(System.currentTimeMillis()<deadline){String reply=shell("cat /data/local/tmp/rootres."+id+" 2>/dev/null || true");if(!reply.isEmpty()){Map<String,String> fields=new HashMap<>();for(String line:reply.split("\n")){int i=line.indexOf('=');if(i>0)fields.put(line.substring(0,i),line.substring(i+1));}if(!id.equals(fields.get("id"))||!boot.equals(fields.get("boot_id"))||!"executed".equals(fields.get("status"))||!"exited".equals(fields.get("result"))||!"0".equals(fields.get("exit"))||!"0".equals(fields.get("signal"))||!"0".equals(fields.get("truncated")))throw new IOException("Rootd не подтвердил успешную установку. Проверьте результат перед повтором.");return;}Thread.sleep(700);}throw new IOException("Нет подтверждения rootd. Установка автоматически не повторяется.");}
 private void install(){if(busy)return;final boolean pin=pinRoot.isChecked();busy(true);new Thread(()->{String stage=null;try{verify();message("Загружаем подписанный каталог выпуска…");JSONObject release=PublicUpdates.manifest(),artifact=release.optJSONObject("station");if(artifact==null||!artifact.optString("profile").equals("max-0921"))throw new IOException("В текущем общем выпуске ещё нет подписанного профиля установки с телефона. Обновите приложение и повторите позже.");message("Загружаем комплект "+release.getString("versionName")+"…");byte[] bundle=PublicUpdates.fetch(artifact.getString("url"),64*1024*1024);if(bundle.length!=artifact.getLong("size")||!sha(bundle).equals(artifact.getString("sha256")))throw new IOException("Подпись каталога верна, но хеш комплекта не совпал");Map<String,byte[]> entries=unpack(bundle);bundle=null;if(!entries.containsKey("manifest.json")||!entries.containsKey("install-device.sh"))throw new IOException("Неполный установщик");JSONObject manifest=new JSONObject(new String(entries.get("manifest.json"),"UTF-8"));Set<String> found=new HashSet<>();Iterator<String> it=manifest.keys();while(it.hasNext())found.add(it.next());if(!found.equals(FILES))throw new IOException("Неизвестный состав профиля");for(String name:FILES){byte[] data=entries.get("payload/"+name);if(data==null||!sha(data).equals(manifest.getString(name)))throw new IOException("Повреждён файл: "+name);}message("Загружаем оригинальный YAM…");byte[] yam=PublicUpdates.fetch(YAM,24*1024*1024);if(!sha(yam).equals(YAM_SHA))throw new IOException("Хеш YAM не совпал");verify();long needed=260000L*1024+yam.length;for(String name:FILES)needed+=entries.get("payload/"+name).length;String[] disk=shell("df -k /data | tail -n 1").trim().split("\\s+");if(disk.length<4||Long.parseLong(disk[3])*1024<needed)throw new IOException("Освободите минимум "+((needed+1048575)/1048576)+" МБ в /data перед установкой");stage="/data/local/tmp/station-studio-install-"+UUID.randomUUID().toString().replace("-","").substring(0,16);shell("mkdir -p "+stage);StringBuilder sums=new StringBuilder();for(String name:FILES){message("Передаём: "+name);push(stage+"/"+name,entries.get("payload/"+name));sums.append(manifest.getString(name)).append(' ').append(name).append('\n');}push(stage+"/yam",yam);sums.append(YAM_SHA).append(" yam\n");push(stage+"/SHA256SUMS",sums.toString().getBytes("US-ASCII"));push(stage+"/install-device.sh",entries.get("install-device.sh"));message("Устанавливаем комплект. Не отключайте питание станции…");root("set -eu\n/system/bin/sh "+stage+"/install-device.sh "+stage+" "+(pin?"1":"0"),stage,true);agent=true;message("Установка подтверждена. Перезапускаем станцию…");if(queue){String rebootStage="/data/local/tmp/station-studio-install-"+UUID.randomUUID().toString().replace("-","").substring(0,16);shell("mkdir -p "+rebootStage);root("setprop sys.powerctl reboot",rebootStage,false);}else{try{shell("setprop sys.powerctl reboot");}catch(Exception ignored){/* Connection loss is expected after this single reboot request. */}}long deadline=System.currentTimeMillis()+180000;boolean ready=false;while(System.currentTimeMillis()<deadline){Thread.sleep(4000);try{String current=shell("cat /proc/sys/kernel/random/boot_id; getprop sys.boot_completed");if(!current.startsWith(boot+"\n")&&current.endsWith("\n1")){ready=true;break;}}catch(Exception ignored){}}if(!ready)throw new IOException("Установка подтверждена, но запуск после перезагрузки ещё не подтверждён. Вернитесь к поиску станции; не повторяйте установку.");shell("am start -n local.station.studio/.TvActivity");message("Станция запущена. На ней откройте «Настройки → Подключить телефон», затем подключитесь по коду.");send("panelInstalled",true);runOnUiThread(()->{connectExisting.setVisibility(View.VISIBLE);install.setText("Обновить комплект и перезапустить");});}catch(Exception e){message((e.getMessage()==null?"Связь прервалась":e.getMessage())+"\nАвтоматический повтор не выполняется.");}finally{busy(false);}},"kontur-install").start();}
